    lanes = I['lanes']
    outregs = block // lanes
    quarter = (
        "_mm256_set_m128i(\n"
        "            _mm_blend_epi16(_mm_set1_epi16((short)a_block[4*_k+2]),\n"
        "                _mm_set1_epi16((short)a_block[4*_k+3]), 0xF0),\n"
        "            _mm_blend_epi16(_mm_set1_epi16((short)a_block[4*_k]),\n"
        "                _mm_set1_epi16((short)a_block[4*_k+1]), 0xF0))")
    lines = []
    lines.append(f"{kw}void simdunpack_u16{name_suffix}_corrected_quarter{mtag}(const {I['reg']} *in, "
                 f"uint16_t *out, const uint32_t bit, "
                 f"const uint16_t *a_block, {I['reg']}* sum) {{")
    lines.append("  switch (bit) {")
    lines.append("  case 0:")
    lines.append("    /* b==0: every OutReg = its quarter anchor; aggregate them. */")
    lines.append("    {")
    lines.append("      size_t _k;")
    lines.append(f"      for (_k = 0; _k < {outregs}; ++_k)")
    lines.append(f"        aggregate_sums_u16{mtag}({quarter}, sum);")
    lines.append("    }")
    lines.append("    (void)in; (void)out;  /* sum-only: no zero-fill of out */")
    lines.append("    break;")
    lines.append("")
    for b in range(1, MAX_BIT + 1):
        lines.append(f"  case {b}:")
        lines.append(f"    __SIMD_fastunpack{b}_16_cquarter{mtag}{name_suffix}(in, out, sum, a_block);")
        lines.append("    break;")
        lines.append("")
    lines.append("  default:")
    lines.append("    break;")
    lines.append("  }")
    lines.append("}")
    lines.append("")
    return "\n".join(lines)


