def gen_unpack_dispatcher_corrected(I, name_suffix=''):
    block = I['block']
    lanes = I['lanes']
    outregs = block // lanes
    lines = []
    lines.append(f"void simdunpack_u16{name_suffix}_corrected(const {I['reg']} *in, "
                 f"uint16_t *out, const uint32_t bit, "
                 f"const {I['reg']} *corrections, {I['reg']}* sum) {{")
    lines.append("  switch (bit) {")
    lines.append("  case 0:")
    lines.append("    /* b==0: every unpacked OutReg is 0; the corrected OutReg")
    lines.append("       is corrections[k], so we aggregate the corrections.")
    lines.append("       (FoR codecs land here when the residual stream is constant 0.) */")
    lines.append("    {")
    lines.append(f"      size_t _k;")
    lines.append(f"      for (_k = 0; _k < {outregs}; ++_k) {{")
    lines.append(f"        aggregate_sums_u16(corrections[_k], sum);")
    lines.append("      }")
    lines.append("    }")
    lines.append("    SIMD_nullunpacker16(in, out);")
    lines.append("    break;")
    lines.append("")
    for b in range(1, MAX_BIT + 1):
        lines.append(f"  case {b}:")
        lines.append(f"    __SIMD_fastunpack{b}_16_corrected{name_suffix}(in, out, sum, corrections);")
        lines.append("    break;")
        lines.append("")
    lines.append("  default:")
    lines.append("    break;")
    lines.append("  }")
    lines.append("}")
    lines.append("")
    return "\n".join(lines)


def gen_unpack_dispatcher_corrected_uniform(I, name_suffix='', agg='unpack', static_=False):
    mtag = '' if agg == 'unpack' else '_' + agg
    kw = "static " if static_ else ""
    block = I['block']
    lanes = I['lanes']
    outregs = block // lanes
    lines = []
    lines.append(f"{kw}void simdunpack_u16{name_suffix}_corrected_uniform{mtag}(const {I['reg']} *in, "
                 f"uint16_t *out, const uint32_t bit, "
                 f"const {I['reg']} anchor, {I['reg']}* sum) {{")
    lines.append("  switch (bit) {")
    lines.append("  case 0:")
    lines.append("    /* b==0: every unpacked OutReg is 0; corrected OutReg = anchor.")
    lines.append("       Aggregate anchor once per OutReg. */")
    lines.append("    {")
    lines.append(f"      size_t _k;")
    lines.append(f"      for (_k = 0; _k < {outregs}; ++_k) {{")
    lines.append(f"        aggregate_sums_u16{mtag}(anchor, sum);")
    lines.append("      }")
    lines.append("    }")
    lines.append("    (void)in; (void)out;  /* sum-only: no zero-fill of out */")
    lines.append("    break;")
    lines.append("")
    for b in range(1, MAX_BIT + 1):
        lines.append(f"  case {b}:")
        lines.append(f"    __SIMD_fastunpack{b}_16_corrected_uniform{mtag}{name_suffix}(in, out, sum, anchor);")
        lines.append("    break;")
        lines.append("")
    lines.append("  default:")
    lines.append("    break;")
    lines.append("  }")
    lines.append("}")
    lines.append("")
    return "\n".join(lines)


def gen_pack_dispatcher_nW(I, W, name_suffix):
    lines = []
    lines.append(f"void simdpack_u16_n{W}(const uint16_t *in, {I['reg']} *out, const uint32_t bit) {{")
    lines.append("  switch (bit) {")
    for b in range(MAX_BIT + 1):
        lines.append(f"  case {b}:")
        lines.append(f"    __SIMD_fastpackwithoutmask{b}_16{name_suffix}(in, out);")
        lines.append("    return;")
        lines.append("")
    lines.append("  default:")
    lines.append("    break;")
    lines.append("  }")
    lines.append("}")
    lines.append("")
    return "\n".join(lines)


def gen_unpack_dispatcher_corrected_uniform_nW(I, W, name_suffix):
    n_outreg = W // I['lanes']
    lines = []
    lines.append(f"void simdunpack_u16_corrected_uniform_n{W}(const {I['reg']} *in, uint16_t *out,")
    lines.append(f"    const uint32_t bit, const {I['reg']} anchor, {I['reg']}* sum) {{")
    lines.append("  switch (bit) {")
    lines.append("  case 0:")
    lines.append("    /* b==0: every unpacked OutReg is 0; corrected OutReg = anchor. */")
    lines.append("    {")
    lines.append(f"      size_t _k;")
    lines.append(f"      for (_k = 0; _k < {n_outreg}; ++_k) {{")
    lines.append(f"        aggregate_sums_u16(anchor, sum);")
    lines.append("      }")
    lines.append("    }")
    lines.append("    (void)in; (void)out;")
    lines.append("    break;")
    lines.append("")
    for b in range(1, MAX_BIT + 1):
        lines.append(f"  case {b}:")
        lines.append(f"    __SIMD_fastunpack{b}_16_corrected_uniform{name_suffix}(in, out, sum, anchor);")
        lines.append("    return;")
        lines.append("")
    lines.append("  default:")
    lines.append("    break;")
    lines.append("  }")
    lines.append("}")
    lines.append("")
    return "\n".join(lines)


def gen_shortlength_pack(I):
    lanes = I['lanes']
    return f"""\
{I['reg']} *simdpack_shortlength_u16(const uint16_t *in, int length, {I['reg']} *out,
                                   const uint32_t bit) {{
  int k;
  int inwordpointer;
  {I['reg']} P;
  uint32_t firstpass;
  if (bit == 0)
    return out;
  if (bit == 16) {{
    memcpy(out, in, length * sizeof(uint16_t));
    return ({I['reg']} *)((uint16_t *)out + length);
  }}
  inwordpointer = 0;
  P = {I['setzero']}();
  for (k = 0; k < length / {lanes}; ++k) {{
    {I['reg']} value = {I['load']}(((const {I['reg']} *)in + k));
    P = {I['or_fn']}(P, {I['slli']}(value, inwordpointer));
    firstpass = 16 - inwordpointer;
    if (bit < firstpass) {{
      inwordpointer += bit;
    }} else {{
      {I['store']}(out++, P);
      P = {I['srli']}(value, firstpass);
      inwordpointer = bit - firstpass;
    }}
  }}
  if (length % {lanes} != 0) {{
    uint16_t buffer[{lanes}];
    {I['reg']} value;
    for (k = 0; k < (length % {lanes}); ++k) {{
      buffer[k] = in[length / {lanes} * {lanes} + k];
    }}
    for (k = (length % {lanes}); k < {lanes}; ++k) {{
      buffer[k] = 0;
    }}
    value = {I['load']}(({I['reg']} *)buffer);
    P = {I['or_fn']}(P, {I['slli']}(value, inwordpointer));
    firstpass = 16 - inwordpointer;
    if (bit < firstpass) {{
      inwordpointer += bit;
    }} else {{
      {I['store']}(out++, P);
      P = {I['srli']}(value, firstpass);
      inwordpointer = bit - firstpass;
    }}
  }}
  if (inwordpointer != 0) {{
    {I['store']}(out++, P);
  }}
  return out;
}}

"""


def gen_shortlength_unpack(I):
    lanes = I['lanes']
    return f"""\
const {I['reg']} *simdunpack_shortlength_u16(const {I['reg']} *in, int length,
                                           uint16_t *out, const uint32_t bit) {{
  int k;
  {I['reg']} maskbits;
  int inwordpointer;
  {I['reg']} P;
  if (length == 0)
    return in;
  if (bit == 0) {{
    for (k = 0; k < length; ++k) {{
      out[k] = 0;
    }}
    return in;
  }}
  if (bit == 16) {{
    memcpy(out, in, length * sizeof(uint16_t));
    return (const {I['reg']} *)((uint16_t *)in + length);
  }}
  maskbits = {I['set1']}((1U << bit) - 1);
  inwordpointer = 0;
  P = {I['load']}(({I['reg']} *)in);
  ++in;
  if (length % {lanes} == 0) {{
    for (k = 0; k + 1 < length / {lanes}; ++k) {{
      {I['reg']} answer = {I['srli']}(P, inwordpointer);
      const uint32_t firstpass = 16 - inwordpointer;
      if (bit < firstpass) {{
        inwordpointer += bit;
      }} else {{
        P = {I['load']}(({I['reg']} *)in);
        ++in;
        answer = {I['or_fn']}({I['slli']}(P, firstpass), answer);
        inwordpointer = bit - firstpass;
      }}
      answer = {I['and_fn']}(maskbits, answer);
      {I['store']}(({I['reg']} *)out, answer);
      out += {lanes};
    }}
    if (k < length / {lanes}) {{
      {I['reg']} answer = {I['srli']}(P, inwordpointer);
      const uint32_t firstpass = 16 - inwordpointer;
      if (bit < firstpass) {{
        inwordpointer += bit;
      }} else if (bit == firstpass) {{
        inwordpointer = 0;
      }} else {{
        P = {I['load']}(({I['reg']} *)in);
        ++in;
        answer = {I['or_fn']}({I['slli']}(P, firstpass), answer);
        inwordpointer = bit - firstpass;
      }}
      answer = {I['and_fn']}(maskbits, answer);
      {I['store']}(({I['reg']} *)out, answer);
      out += {lanes};
    }}
  }} else {{
    for (k = 0; k < length / {lanes}; ++k) {{
      {I['reg']} answer = {I['srli']}(P, inwordpointer);
      const uint32_t firstpass = 16 - inwordpointer;
      if (bit < firstpass) {{
        inwordpointer += bit;
      }} else {{
        P = {I['load']}(({I['reg']} *)in);
        ++in;
        answer = {I['or_fn']}({I['slli']}(P, firstpass), answer);
        inwordpointer = bit - firstpass;
      }}
      answer = {I['and_fn']}(maskbits, answer);
      {I['store']}(({I['reg']} *)out, answer);
      out += {lanes};
    }}
    uint16_t buffer[{lanes}];
    {I['reg']} answer = {I['srli']}(P, inwordpointer);
    const uint32_t firstpass = 16 - inwordpointer;
    if (bit < firstpass) {{
      inwordpointer += bit;
    }} else if (bit == firstpass) {{
      inwordpointer = 0;
    }} else {{
      P = {I['load']}(({I['reg']} *)in);
      ++in;
      answer = {I['or_fn']}({I['slli']}(P, firstpass), answer);
      inwordpointer = bit - firstpass;
    }}
    answer = {I['and_fn']}(maskbits, answer);
    {I['store']}(({I['reg']} *)buffer, answer);
    for (k = 0; k < (length % {lanes}); ++k) {{
      *out = buffer[k];
      ++out;
    }}
  }}
  return in;
}}

"""


def gen_utility_functions(I):
    width = I['width']
    lanes = I['lanes']
    block = I['block']

    if width == 128:
        oras_body = f"""\
/* returns the integer logarithm of v (bit width) for uint16 */
static uint32_t bits_u16(const uint16_t v) {{
  return v == 0 ? 0 : 32 - __builtin_clz((uint32_t)v);
}}

static uint32_t oras_u16(const {I['reg']} accumulator) {{
  /* Horizontal OR of {lanes} uint16 lanes into a single uint16 value */
  const {I['reg']} _tmp1 = {I['or_fn']}(
      _mm_srli_si128(accumulator, 8), accumulator);
  const {I['reg']} _tmp2 = {I['or_fn']}(
      _mm_srli_si128(_tmp1, 4), _tmp1);
  const {I['reg']} _tmp3 = {I['or_fn']}(
      _mm_srli_si128(_tmp2, 2), _tmp2);
  return (uint16_t)_mm_extract_epi16(_tmp3, 0);
}}
"""
    else:
        oras_body = f"""\
/* returns the integer logarithm of v (bit width) for uint16 */
static uint32_t bits_u16(const uint16_t v) {{
  return v == 0 ? 0 : 32 - __builtin_clz((uint32_t)v);
}}

static uint32_t oras_u16(const {I['reg']} accumulator) {{
  /* Horizontal OR of {lanes} uint16 lanes into a single uint16 value */
  __m128i lo = _mm256_castsi256_si128(accumulator);
  __m128i hi = _mm256_extracti128_si256(accumulator, 1);
  __m128i combined = _mm_or_si128(lo, hi);
  const __m128i _tmp1 = _mm_or_si128(
      _mm_srli_si128(combined, 8), combined);
  const __m128i _tmp2 = _mm_or_si128(
      _mm_srli_si128(_tmp1, 4), _tmp1);
  const __m128i _tmp3 = _mm_or_si128(
      _mm_srli_si128(_tmp2, 2), _tmp2);
  return (uint16_t)_mm_extract_epi16(_tmp3, 0);
}}
"""

    if width == 128:
        hsum = """\
  /* Horizontal reduction: 4 x int32 -> 1 x int32 */
  __m128i s = sum;
  s = _mm_add_epi32(s, _mm_shuffle_epi32(s, _MM_SHUFFLE(1,0,3,2)));
  s = _mm_add_epi32(s, _mm_shuffle_epi32(s, _MM_SHUFFLE(2,3,0,1)));

  uint32_t finalsum = (uint32_t)_mm_cvtsi128_si32(s);"""
    else:
        hsum = """\
  /* 256-bit horizontal reduction */
  __m128i lo = _mm256_castsi256_si128(sum);
  __m128i hi = _mm256_extracti128_si256(sum, 1);
  __m128i s = _mm_add_epi32(lo, hi);
  s = _mm_add_epi32(s, _mm_shuffle_epi32(s, _MM_SHUFFLE(1,0,3,2)));
  s = _mm_add_epi32(s, _mm_shuffle_epi32(s, _MM_SHUFFLE(2,3,0,1)));

  uint32_t finalsum = (uint32_t)_mm_cvtsi128_si32(s);"""

    if width == 256:
        delta_length = f"""\
/* LOCAL delta variant: SIMD blocks run zigzag_dec + per-OutReg prefix sum +
   aggregate (no inter-OutReg carry). Tail does scalar zigzag-decode + prefix
   sum, with prev resetting every 16 elements (rounded_length is a multiple
   of 16 so the tail starts at a 16-boundary). */
const {I['reg']} *simdunpack_length_u16_delta_local(const {I['reg']} *in,
                                                  size_t length, uint16_t *out,
                                                  const uint32_t bit,
                                                  uint32_t *outsum) {{
  {I['reg']} sum = {I['setzero']}();
  size_t k;
  for (k = 0; k < length / SIMDBlockSize_u16; ++k) {{
    simdunpack_u16_delta_local(in, out, bit, &sum);
    out += SIMDBlockSize_u16;
    in += bit;
  }}
{hsum}

  /* Tail: scalar un-zigzag + un-delta with prev resetting every 16 elements. */
  size_t remainder = length % SIMDBlockSize_u16;
  if (remainder > 0) {{
    in = simdunpack_shortlength_u16(in, remainder, out, bit);
    uint16_t prev = 0;
    size_t i;
    for (i = 0; i < remainder; ++i) {{
      if ((i & 15) == 0) prev = 0;
      uint16_t delta = ZigzagDec16_simdcomp(out[i]);
      uint16_t cur = (uint16_t)(prev + delta);
      finalsum += cur;
      prev = cur;
    }}
  }}
  *outsum = finalsum;
  return in;
}}

/* CARRY delta variant: SIMD blocks thread a broadcast-carry __m256i across
   OutRegs/blocks. Tail scalar continues the chain by seeding prev from the
   last broadcast-carry value. */
const {I['reg']} *simdunpack_length_u16_delta_carry(const {I['reg']} *in,
                                                  size_t length, uint16_t *out,
                                                  const uint32_t bit,
                                                  uint32_t *outsum) {{
  {I['reg']} sum = {I['setzero']}();
  uint16_t carry = 0;
  size_t k;
  for (k = 0; k < length / SIMDBlockSize_u16; ++k) {{
    simdunpack_u16_delta_carry(in, out, bit, &carry, &sum);
    out += SIMDBlockSize_u16;
    in += bit;
  }}
{hsum}

  /* Tail: scalar un-zigzag + un-delta seeded from the scalar carry. */
  size_t remainder = length % SIMDBlockSize_u16;
  if (remainder > 0) {{
    in = simdunpack_shortlength_u16(in, remainder, out, bit);
    uint16_t prev = carry;
    size_t i;
    for (i = 0; i < remainder; ++i) {{
      uint16_t delta = ZigzagDec16_simdcomp(out[i]);
      uint16_t cur = (uint16_t)(prev + delta);
      finalsum += cur;
      prev = cur;
    }}
  }}
  *outsum = finalsum;
  return in;
}}

"""
    else:
        delta_length = ""

    return f"""\
{oras_body}

uint32_t maxbits_length_u16(const uint16_t *in, size_t length) {{
  size_t k;
  size_t lengthdividedby{lanes} = length / {lanes};
  size_t offset = lengthdividedby{lanes} * {lanes};
  uint32_t bigxor = 0;
  if (lengthdividedby{lanes} > 0) {{
    const {I['reg']} *pin = (const {I['reg']} *)(in);
    {I['reg']} accumulator = {I['load']}(pin);
    k = 1;
    for (; {lanes} * k < {lanes} * lengthdividedby{lanes}; ++k) {{
      {I['reg']} newvec = {I['load']}(pin + k);
      accumulator = {I['or_fn']}(accumulator, newvec);
    }}
    bigxor = oras_u16(accumulator);
  }}
  for (k = offset; k < length; ++k)
    bigxor |= in[k];
  return bits_u16((uint16_t)bigxor);
}}

int simdpack_compressedbytes_u16(int length, const uint32_t bit) {{
  if (bit == 0)
    return 0;
  if (bit == 16) {{
    return length * sizeof(uint16_t);
  }}
  /* Each group of {lanes} uint16 lanes packs to ({lanes} * bit) bits = bit bytes per group.
     Total groups = (length + {lanes - 1}) / {lanes}.  Round up to {I['reg']} boundary. */
  return (((length + {lanes - 1}) / {lanes}) * bit + 15) / 16 * sizeof({I['reg']});
}}

{I['reg']} *simdpack_length_u16(const uint16_t *in, size_t length, {I['reg']} *out,
                              const uint32_t bit) {{
  size_t k;
  for (k = 0; k < length / SIMDBlockSize_u16; ++k) {{
    simdpack_u16(in, out, bit);
    in += SIMDBlockSize_u16;
    out += bit;
  }}
  return simdpack_shortlength_u16(in, length % SIMDBlockSize_u16, out, bit);
}}

const {I['reg']} *simdunpack_length_u16(const {I['reg']} *in, size_t length,
                                      uint16_t *out, const uint32_t bit,
                                      uint32_t *outsum) {{
  {I['reg']} sum = {I['setzero']}();
  size_t k;
  for (k = 0; k < length / SIMDBlockSize_u16; ++k) {{
    simdunpack_u16(in, out, bit, &sum);
    out += SIMDBlockSize_u16;
    in += bit;
  }}
{hsum}

  /* Handle remainder with scalar sum */
  size_t remainder = length % SIMDBlockSize_u16;
  if (remainder > 0) {{
    in = simdunpack_shortlength_u16(in, remainder, out, bit);
    size_t i;
    for (i = 0; i < remainder; ++i) {{
      finalsum += out[i];
    }}
  }}
  *outsum = finalsum;
  return in;
}}

{delta_length}"""


def gen_shuffle16_table():
    """Left-pack/expand pshufb table for the 8-lane (u16) exception merge.
    kShuffle16[m] maps consecutively-packed u16 (source lanes 0..popcnt(m)-1) to
    the set-bit lanes of the 8-bit mask m, zeroing unset lanes (0xFF -> 0)."""
    rows = []
    for m in range(256):
        b = []
        src = 0
        for lane in range(8):
            if m & (1 << lane):
                b += [2 * src, 2 * src + 1]; src += 1
            else:
                b += [0xFF, 0xFF]
        rows.append("  {" + ",".join(str(x) for x in b) + "}")
    return ("static const unsigned char kShuffle16[256][16] = {\n"
            + ",\n".join(rows) + "\n};\n")


def gen_pfor_dispatcher(I):
    lines = []
    lines.append("void simdunpack_u16_pfor(const __m256i *in, uint16_t *out, "
                 "const uint32_t bit, __m256i *sum,")
    lines.append("                         const uint16_t *pex, const uint16_t *bm16) {")
    lines.append("  switch (bit) {")
    # b == 0: low bits are all zero; corrected OutReg = left-packed excess.
    lines.append("  case 0: {")
    lines.append("    const uint16_t *_pex = pex; int v; (void)in; (void)out;")
    lines.append("    for (v = 0; v < 16; ++v) {")
    lines.append("      unsigned _m = bm16[v];")
    lines.append("      __m256i _exc = _mm256_set_m128i(")
    lines.append("          _mm_loadu_si128((const __m128i *)(_pex + _mm_popcnt_u32(_m & 0xFF))),")
    lines.append("          _mm_loadu_si128((const __m128i *)_pex));")
    lines.append("      __m256i _shuf = _mm256_set_m128i(")
    lines.append("          _mm_loadu_si128((const __m128i *)kShuffle16[_m >> 8]),")
    lines.append("          _mm_loadu_si128((const __m128i *)kShuffle16[_m & 0xFF]));")
    lines.append("      _exc = _mm256_shuffle_epi8(_exc, _shuf);")
    lines.append("      aggregate_sums_u16(_exc, sum);")
    lines.append("      _pex += _mm_popcnt_u32(_m);")
    lines.append("    }")
    lines.append("    break; }")
    for b in range(1, MAX_BIT):  # 1..15 (b==16 has no exceptions -> never called)
        lines.append(f"  case {b}:")
        lines.append(f"    __SIMD_fastunpack{b}_16_pfor(in, out, sum, pex, bm16);")
        lines.append("    break;")
    lines.append("  default: break;")
    lines.append("  }")
    lines.append("}")
    lines.append("")
    return "\n".join(lines)


def gen_pfor_corrected_dispatcher(I, anchor_kind, shg=None, name_suffix='',
                                  agg='unpack', static=True):
    """STATIC `_il` dispatcher for a fused TurboPFor-FoR exception block: unpack
    low bits, in-register PFOR exception merge, FoR anchor, then aggregate.
    anchor_kind ∈ {uniform, scalar, half, quarter} (256-bit only).

    agg ∈ {unpack, madd}  → bc: anchor added to the OutReg (SIMD), then aggregate.
    agg ∈ {nobc, nobc_madd}→ no SIMD anchor; residual aggregated + the anchor's
        contribution accumulated into *scalar_acc via aggregate_sums_u16_nobc*.

    b==0 (low bits all zero): residual = the left-packed excess; bc adds anchor(v)
    in-register, nobc routes the same excess through the nobc aggregate so the
    anchor still lands in *scalar_acc (must NOT be skipped — anchors are nonzero)."""
    assert I['width'] == 256
    assert anchor_kind in ('uniform', 'scalar', 'half', 'quarter')
    is_nobc = agg in ('nobc', 'nobc_madd')
    nm = '_madd' if agg == 'nobc_madd' else ''   # nobc helper madd suffix
    mtag = '' if agg == 'unpack' else '_' + agg
    s1 = I['set1']
    if anchor_kind == 'scalar':
        assert shg is not None
        tag = f'pfor_cscalar{shg}'
    else:
        tag = {'uniform': 'pfor_cuniform', 'half': 'pfor_chalf',
               'quarter': 'pfor_cquarter'}[anchor_kind]

    # bc anchor C-expression (runtime loop var _k) for the b==0 in-register add.
    if anchor_kind == 'uniform':
        def aexpr(k): return "anchor"
    elif anchor_kind == 'scalar':
        def aexpr(k): return f"{s1}((short)a_block[{k} >> {shg}])"
    elif anchor_kind == 'half':
        def aexpr(k): return (f"_mm256_blend_epi32({s1}((short)a_block[2*{k}]), "
                              f"{s1}((short)a_block[2*{k}+1]), 0xF0)")
    else:  # quarter
        def aexpr(k): return (
            "_mm256_set_m128i("
            f"_mm_blend_epi16(_mm_set1_epi16((short)a_block[4*{k}+2]), "
            f"_mm_set1_epi16((short)a_block[4*{k}+3]), 0xF0), "
            f"_mm_blend_epi16(_mm_set1_epi16((short)a_block[4*{k}]), "
            f"_mm_set1_epi16((short)a_block[4*{k}+1]), 0xF0))")

    # nobc b==0 helper call (residual = _exc; scalar anchor accumulated into _sacc).
    def nobc_b0(k):
        if anchor_kind in ('uniform', 'scalar'):
            idx = "a_block" if anchor_kind == 'uniform' else f"a_block + ({k} >> {shg})"
            return f"aggregate_sums_u16_nobc{nm}(_exc, {idx}, &_sacc, (nobc_sum_t*)sum);"
        if anchor_kind == 'half':
            return f"aggregate_sums_u16_nobc_half{nm}(_exc, a_block + 2*{k}, &_sacc, (nobc_sum_t*)sum);"
        return f"aggregate_sums_u16_nobc_quarter{nm}(_exc, a_block + 4*{k}, &_sacc, (nobc_sum_t*)sum);"

    # Signature: nobc always passes a_block + scalar_acc (uniform too); bc uniform
    # passes a broadcast __m256i anchor, bc others pass a_block.
    if is_nobc:
        anchor_param = ("const uint16_t * __restrict__ a_block, "
                        "uint64_t * __restrict__ scalar_acc")
        call_anchor = "a_block, scalar_acc"
    elif anchor_kind == 'uniform':
        anchor_param = f"const {I['reg']} anchor"
        call_anchor = "anchor"
    else:
        anchor_param = "const uint16_t *a_block"
        call_anchor = "a_block"

    kw = "static " if static else ""
    lines = []
    lines.append(f"{kw}void simdunpack_u16{name_suffix}_{tag}{mtag}(const {I['reg']} *in, "
                 f"uint16_t *out, const uint32_t bit,")
    lines.append(f"    {anchor_param}, {I['reg']} *sum, const uint16_t *pex, const uint16_t *bm16) {{")
    lines.append("  switch (bit) {")
    lines.append("  case 0: {")
    lines.append("    const uint16_t *_pex = pex; int v; (void)in; (void)out;")
    if is_nobc:
        lines.append("    uint64_t _sacc = 0;")
    lines.append("    for (v = 0; v < 16; ++v) {")
    lines.append("      unsigned _m = bm16[v];")
    lines.append(f"      {I['reg']} _exc = _mm256_set_m128i(")
    lines.append("          _mm_loadu_si128((const __m128i *)(_pex + _mm_popcnt_u32(_m & 0xFF))),")
    lines.append("          _mm_loadu_si128((const __m128i *)_pex));")
    lines.append(f"      {I['reg']} _shuf = _mm256_set_m128i(")
    lines.append("          _mm_loadu_si128((const __m128i *)kShuffle16[_m >> 8]),")
    lines.append("          _mm_loadu_si128((const __m128i *)kShuffle16[_m & 0xFF]));")
    lines.append("      _exc = _mm256_shuffle_epi8(_exc, _shuf);")
    if is_nobc:
        lines.append(f"      {nobc_b0('v')}")
    else:
        lines.append(f"      aggregate_sums_u16{mtag}({I['add16']}(_exc, {aexpr('v')}), sum);")
    lines.append("      _pex += _mm_popcnt_u32(_m);")
    lines.append("    }")
    if is_nobc:
        lines.append("    *scalar_acc += _sacc;")
    lines.append("    break; }")
    for b in range(1, MAX_BIT):  # 1..15
        lines.append(f"  case {b}:")
        lines.append(f"    __SIMD_fastunpack{b}_16_{tag}{mtag}{name_suffix}"
                     f"(in, out, sum, {call_anchor}, pex, bm16);")
        lines.append("    break;")
    lines.append("  default: break;")
    lines.append("  }")
    lines.append("}")
    lines.append("")
    return "\n".join(lines)


def main():
    parser = argparse.ArgumentParser(
        description='Generate SIMD bit-packing for uint16')
    parser.add_argument('--width', type=int, choices=[128, 256], default=128,
                        help='Register width in bits (128=AVX, 256=AVX2)')
    parser.add_argument('--suffix', default='',
                        help='Public-symbol suffix for a minimal self-contained '
                             'variant (e.g. _w128). Emits only simdpack_u16<sfx> / '
                             'simdunpack_u16<sfx> + their statics.')
    parser.add_argument('--pfor', action='store_true',
                        help='Emit a self-contained simdunpack_u16_pfor variant '
                             '(in-register PFOR exception merge) to its own file.')
    parser.add_argument('--corrected', action='store_true',
                        help='Emit a self-contained FoR-corrected + data-store '
                             'unpack variant (simdunpack_u16<suffix>_corrected and '
                             'simdunpack_u16<suffix>_store) to its own file. Pair '
                             'with --width 128 --suffix _w128 for the 128-bit FoR '
                             'fused codecs.')
    parser.add_argument('--inline-decode', action='store_true',
                        help='Emit a header with STATIC plain + pfor decode kernels '
                             '(simdunpack_u16_il / simdunpack_u16_pfor_il) to be '
                             '#included into the decoder TU so they inline and the '
                             'sum accumulator stays register-resident.')
    parser.add_argument('--inline-decode-for', action='store_true',
                        help='Emit a header with STATIC FoR-corrected decode '
                             'kernels — both no-exception (corrected_*_il, for '
                             'PLAIN blocks) and PFOR-exception (pfor_c*_il) — for '
                             'each anchor mode (uniform/cscalar0-3/half/quarter) '
                             'and aggregate (unpack/madd/noagg). #included into the '
                             'fused TurboPFor-FoR decoder TU. AVX2 (256-bit) only.')
    parser.add_argument('--anc', action='store_true',
                        help='Generate nobc (plain aggregate + scalar anchor accumulation) '
                             'variants. Emits simdbitpacking_u16{suffix}_nobc.c with '
                             'corrected_uniform/cscalar/half/quarter nobc and nobc_madd '
                             'kernels. Requires --suffix and --corrected-style width.')
    parser.add_argument('--output', default=None,
                        help='Output .c path (default: ../src/simdbitpacking_u16.c)')
    args = parser.parse_args()

    I = intrinsics(args.width)
    lanes = args.width // LANE_BITS
    block = lanes * MAX_BIT  # 128 for 128-bit, 256 for 256-bit
    I['lanes'] = lanes
    I['block'] = block
    I['width'] = args.width

    # Inline-decode header: STATIC plain + pfor kernels (suffix _il) for #include
    # into the decoder TU. Inlining folds the switch and keeps `sum` in a register
    # across all sub-blocks (no spill across a cross-TU call).
    if getattr(args, 'inline_decode', False):
        assert args.width == 256, "inline-decode variant is AVX2 (256-bit) only"
        reg = I['reg']
        head = (
            "/**\n"
            " * Auto-generated STATIC decode kernels for same-TU inlining.\n"
            " * Generated by gen_simdbitpacking_u16.py --inline-decode (AVX2, 16 lanes).\n"
            " * #include this into the decoder .c. Symbols: simdunpack_u16_il /\n"
            " * simdunpack_u16_pfor_il (both static). BSD License.\n"
            " */\n"
            "#include <immintrin.h>\n#include <stdint.h>\n#include <stddef.h>\n#include <string.h>\n\n"
            f"static const {reg} kZero = {{0, 0, 0, 0}};\n\n"
            f"static void aggregate_sums_u16({reg} OutReg, {reg}* sum) {{\n"
            f"    *sum = {I['add']}(*sum, {I['unpacklo']}(OutReg, kZero));\n"
            f"    *sum = {I['add']}(*sum, {I['unpackhi']}(OutReg, kZero));\n"
            "}\n\n"
            "/* madd-widen aggregate (one port-0/1 op vs two port-5 shuffles).\n"
            "   Signed — valid only when every summed value < 2^15. Used by the\n"
            "   _madd decode kernels so the TurboPFor nobc residual decode matches\n"
            "   simdcomp's nobc_madd aggregate for a fair comparison. */\n"
            f"__attribute__((unused))\n"
            f"static void aggregate_sums_u16_madd({reg} OutReg, {reg}* sum) {{\n"
            f"    *sum = {I['add']}(*sum, {I['madd16']}(OutReg, {I['set1']}(1)));\n"
            "}\n\n")
        out = [head, gen_null_unpacker(I), gen_shuffle16_table(), "\n"]
        # Plain unpack (static, _il)
        for bit in range(1, MAX_BIT + 1):
            out.append(gen_unpack_function(bit, I, mode='plain', name_suffix='_il'))
        plain = ["static void simdunpack_u16_il(const __m256i *in, uint16_t *out, "
                 "const uint32_t bit, __m256i* sum) {", "  switch (bit) {",
                 "  case 0: SIMD_nullunpacker16(in, out); break;"]
        for b in range(1, MAX_BIT + 1):
            plain.append(f"  case {b}: __SIMD_fastunpack{b}_16_il(in, out, sum); break;")
        plain += ["  default: break;", "  }", "}", ""]
        out.append("\n".join(plain))
        # PFOR unpack (static, _il)
        for bit in range(1, MAX_BIT):  # 1..15
            out.append(gen_unpack_function(bit, I, mode='pfor', name_suffix='_il'))
        pf = ["static void simdunpack_u16_pfor_il(const __m256i *in, uint16_t *out, "
              "const uint32_t bit, __m256i *sum,",
              "                                    const uint16_t *pex, const uint16_t *bm16) {",
              "  switch (bit) {"]
        pf.append("  case 0: {")
        pf.append("    const uint16_t *_pex = pex; int v; (void)in; (void)out;")
        pf.append("    for (v = 0; v < 16; ++v) {")
        pf.append("      unsigned _m = bm16[v];")
        pf.append("      __m256i _exc = _mm256_set_m128i(")
        pf.append("          _mm_loadu_si128((const __m128i *)(_pex + _mm_popcnt_u32(_m & 0xFF))),")
        pf.append("          _mm_loadu_si128((const __m128i *)_pex));")
        pf.append("      __m256i _shuf = _mm256_set_m128i(")
        pf.append("          _mm_loadu_si128((const __m128i *)kShuffle16[_m >> 8]),")
        pf.append("          _mm_loadu_si128((const __m128i *)kShuffle16[_m & 0xFF]));")
        pf.append("      _exc = _mm256_shuffle_epi8(_exc, _shuf);")
        pf.append("      aggregate_sums_u16(_exc, sum);")
        pf.append("      _pex += _mm_popcnt_u32(_m);")
        pf.append("    }")
        pf.append("    break; }")
        for b in range(1, MAX_BIT):
            pf.append(f"  case {b}: __SIMD_fastunpack{b}_16_pfor_il(in, out, sum, pex, bm16); break;")
        pf += ["  default: break;", "  }", "}", ""]
        out.append("\n".join(pf))
        # ── madd aggregate variants: identical bit-unpack + PFOR merge, but the
        #    per-OutReg aggregate is madd (port 0/1) instead of unpack-widen
        #    (port 5). p4ndec256v16_sum_madd uses these so nobc residual decode
        #    sums the same way simdcomp's nobc_madd does (fair comparison).
        for bit in range(1, MAX_BIT + 1):
            out.append(gen_unpack_function(bit, I, mode='plain', name_suffix='_il', agg='madd'))
        plain_m = ["static void simdunpack_u16_il_madd(const __m256i *in, uint16_t *out, "
                   "const uint32_t bit, __m256i* sum) {", "  switch (bit) {",
                   "  /* b==0: all-zero block adds 0 to the fused sum (out unused) → no-op. */",
                   "  case 0: (void)in; (void)out; break;"]
        for b in range(1, MAX_BIT + 1):
            plain_m.append(f"  case {b}: __SIMD_fastunpack{b}_16_madd_il(in, out, sum); break;")
        plain_m += ["  default: break;", "  }", "}", ""]
        out.append("\n".join(plain_m))
        for bit in range(1, MAX_BIT):
            out.append(gen_unpack_function(bit, I, mode='pfor', name_suffix='_il', agg='madd'))
        pfm = ["static void simdunpack_u16_pfor_il_madd(const __m256i *in, uint16_t *out, "
               "const uint32_t bit, __m256i *sum,",
               "                                    const uint16_t *pex, const uint16_t *bm16) {",
               "  switch (bit) {",
               "  case 0: {",
               "    const uint16_t *_pex = pex; int v; (void)in; (void)out;",
               "    for (v = 0; v < 16; ++v) {",
               "      unsigned _m = bm16[v];",
               "      __m256i _exc = _mm256_set_m128i(",
               "          _mm_loadu_si128((const __m128i *)(_pex + _mm_popcnt_u32(_m & 0xFF))),",
               "          _mm_loadu_si128((const __m128i *)_pex));",
               "      __m256i _shuf = _mm256_set_m128i(",
               "          _mm_loadu_si128((const __m128i *)kShuffle16[_m >> 8]),",
               "          _mm_loadu_si128((const __m128i *)kShuffle16[_m & 0xFF]));",
               "      _exc = _mm256_shuffle_epi8(_exc, _shuf);",
               "      aggregate_sums_u16_madd(_exc, sum);",
               "      _pex += _mm_popcnt_u32(_m);",
               "    }",
               "    break; }"]
        for b in range(1, MAX_BIT):
            pfm.append(f"  case {b}: __SIMD_fastunpack{b}_16_pfor_madd_il(in, out, sum, pex, bm16); break;")
        pfm += ["  default: break;", "  }", "}", ""]
        out.append("\n".join(pfm))
        out_path = args.output or os.path.join(
            os.path.dirname(os.path.abspath(__file__)), '..', 'src',
            'simdbitpacking_u16_decode_inl.h')
        with open(out_path, 'w') as f:
            f.write("".join(out))
        print(f"Generated {out_path}")
        return

    # Inline FoR-corrected decode header (STATIC _il kernels) for the fused
    # TurboPFor-FoR decoder. For each anchor mode (uniform/cscalar0-3/half/quarter)
    # and aggregate (unpack/madd/noagg) it emits BOTH:
    #   simdunpack_u16_il_<corrected_mode>   — no-exception (PLAIN) blocks: unpack
    #       low bits + per-OutReg anchor add + aggregate (same as the simdcomp FoR
    #       kernels, but static for in-TU inlining).
    #   simdunpack_u16_il_<pfor_corrected_mode> — exception blocks: unpack low bits
    #       + in-register PFOR exception merge + anchor add + aggregate.
    # #included into vp4d256v16_for_fused.c so everything inlines and `sum` stays
    # in a YMM register across blocks (no cross-TU spill).
    if getattr(args, 'inline_decode_for', False):
        assert args.width == 256, "inline-decode-for is AVX2 (256-bit) only"
        reg = I['reg']
        head = (
            "/**\n"
            " * Auto-generated STATIC FoR-corrected decode kernels for same-TU\n"
            " * inlining (fused TurboPFor-FoR). Generated by\n"
            " * gen_simdbitpacking_u16.py --inline-decode-for (AVX2, 16 lanes).\n"
            " * #include this into the decoder .c. BSD License.\n"
            " */\n"
            "#include <immintrin.h>\n#include <stdint.h>\n#include <stddef.h>\n#include <string.h>\n\n"
            f"static const {reg} kZero = {{0, 0, 0, 0}};\n\n"
            f"static void aggregate_sums_u16({reg} OutReg, {reg}* sum) {{\n"
            f"    *sum = {I['add']}(*sum, {I['unpacklo']}(OutReg, kZero));\n"
            f"    *sum = {I['add']}(*sum, {I['unpackhi']}(OutReg, kZero));\n"
            "}\n\n"
            f"__attribute__((unused))\n"
            f"static void aggregate_sums_u16_madd({reg} OutReg, {reg}* sum) {{\n"
            f"    *sum = {I['add']}(*sum, {I['madd16']}(OutReg, {I['set1']}(1)));\n"
            "}\n\n"
            f"__attribute__((unused))\n"
            f"static void aggregate_sums_u16_noagg({reg} OutReg, {reg}* sum) {{\n"
            f"    *sum = {I['xor_fn']}(*sum, OutReg);\n"
            "}\n\n")
        # nobc helpers: plain widen-sum into *sum + scalar anchor contribution into
        # *scalar_acc. nobc_sum_t is a vector typedef WITHOUT __may_alias__ so the
        # *sum writes don't force GCC to reload a[] between OutRegs (the 2.8× trap).
        _lanes = I['lanes']; _hl = _lanes // 2; _ql = _lanes // 4
        def _nobc_def(name, scalar_expr, use_madd):
            agg_line = (f"    _sv = {I['add']}(_sv, {I['madd16']}(OutReg, {I['set1']}(1)));\n"
                        if use_madd else
                        f"    _sv = {I['add']}(_sv, {I['unpacklo']}(OutReg, kZero));\n"
                        f"    _sv = {I['add']}(_sv, {I['unpackhi']}(OutReg, kZero));\n")
            return (f"__attribute__((unused))\n"
                    f"static void {name}({reg} OutReg, const uint16_t * __restrict__ a,"
                    f" uint64_t * __restrict__ scalar_acc, nobc_sum_t * __restrict__ sum) {{\n"
                    f"    {reg} _sv = ({reg})(*sum);\n{agg_line}"
                    f"    *sum = (nobc_sum_t)_sv;\n"
                    f"    *scalar_acc += {scalar_expr};\n}}\n\n")
        head += (
            f"typedef int nobc_sum_t __attribute__((vector_size(32)));\n\n"
            + _nobc_def("aggregate_sums_u16_nobc", f"{_lanes}ULL * (uint64_t)a[0]", False)
            + _nobc_def("aggregate_sums_u16_nobc_madd", f"{_lanes}ULL * (uint64_t)a[0]", True)
            + _nobc_def("aggregate_sums_u16_nobc_half",
                        f"{_hl}ULL * (uint64_t)a[0] + {_hl}ULL * (uint64_t)a[1]", False)
            + _nobc_def("aggregate_sums_u16_nobc_half_madd",
                        f"{_hl}ULL * (uint64_t)a[0] + {_hl}ULL * (uint64_t)a[1]", True)
            + _nobc_def("aggregate_sums_u16_nobc_quarter",
                        f"{_ql}ULL * ((uint64_t)a[0] + (uint64_t)a[1] + (uint64_t)a[2] + (uint64_t)a[3])", False)
            + _nobc_def("aggregate_sums_u16_nobc_quarter_madd",
                        f"{_ql}ULL * ((uint64_t)a[0] + (uint64_t)a[1] + (uint64_t)a[2] + (uint64_t)a[3])", True))
        out = [head, gen_null_unpacker(I), gen_shuffle16_table(), "\n"]
        ns = '_il'
        for agg in ('unpack', 'madd', 'noagg'):
            # ── no-exception (PLAIN) corrected kernels: bits 0..16 ──
            for bit in range(1, MAX_BIT + 1):
                out.append(gen_unpack_function(bit, I, mode='corrected_uniform',
                                               name_suffix=ns, agg=agg))
            out.append(gen_unpack_dispatcher_corrected_uniform(
                I, name_suffix=ns, agg=agg, static_=True))
            for shg in range(4):
                for bit in range(1, MAX_BIT + 1):
                    out.append(gen_unpack_function(bit, I, mode='corrected_scalar',
                                                   name_suffix=ns, shg=shg, agg=agg))
                out.append(gen_unpack_dispatcher_corrected_scalar(
                    I, shg, name_suffix=ns, agg=agg, static_=True))
            for bit in range(1, MAX_BIT + 1):
                out.append(gen_unpack_function(bit, I, mode='corrected_half',
                                               name_suffix=ns, agg=agg))
            out.append(gen_unpack_dispatcher_corrected_half(
                I, name_suffix=ns, agg=agg, static_=True))
            for bit in range(1, MAX_BIT + 1):
                out.append(gen_unpack_function(bit, I, mode='corrected_quarter',
                                               name_suffix=ns, agg=agg))
            out.append(gen_unpack_dispatcher_corrected_quarter(
                I, name_suffix=ns, agg=agg, static_=True))
            # ── PFOR-exception corrected kernels: bits 1..15 ──
            for bit in range(1, MAX_BIT):
                out.append(gen_unpack_function(bit, I, mode='pfor_corrected_uniform',
                                               name_suffix=ns, agg=agg))
            out.append(gen_pfor_corrected_dispatcher(I, 'uniform', name_suffix=ns, agg=agg))
            for shg in range(4):
                for bit in range(1, MAX_BIT):
                    out.append(gen_unpack_function(bit, I, mode='pfor_corrected_scalar',
                                                   name_suffix=ns, shg=shg, agg=agg))
                out.append(gen_pfor_corrected_dispatcher(I, 'scalar', shg=shg,
                                                         name_suffix=ns, agg=agg))
            for bit in range(1, MAX_BIT):
                out.append(gen_unpack_function(bit, I, mode='pfor_corrected_half',
                                               name_suffix=ns, agg=agg))
            out.append(gen_pfor_corrected_dispatcher(I, 'half', name_suffix=ns, agg=agg))
            for bit in range(1, MAX_BIT):
                out.append(gen_unpack_function(bit, I, mode='pfor_corrected_quarter',
                                               name_suffix=ns, agg=agg))
            out.append(gen_pfor_corrected_dispatcher(I, 'quarter', name_suffix=ns, agg=agg))
        # ── nobc: scalar anchor accumulation (no SIMD correction). PLAIN blocks use
        #    corrected_*_nobc; exception blocks use pfor_c*_nobc. ──
        for av in ('nobc', 'nobc_madd'):
            # no-exception (PLAIN) corrected nobc kernels
            for bit in range(1, MAX_BIT + 1):
                out.append(gen_unpack_function(bit, I, mode='corrected_uniform',
                                               name_suffix=ns, agg=av))
            out.append(gen_unpack_dispatcher_corrected_uniform_nobc(
                I, name_suffix=ns, agg_variant=av, static_=True))
            for shg in range(4):
                for bit in range(1, MAX_BIT + 1):
                    out.append(gen_unpack_function(bit, I, mode='corrected_scalar',
                                                   name_suffix=ns, shg=shg, agg=av))
                out.append(gen_unpack_dispatcher_corrected_scalar_nobc(
                    I, shg, name_suffix=ns, agg_variant=av, static_=True))
            for bit in range(1, MAX_BIT + 1):
                out.append(gen_unpack_function(bit, I, mode='corrected_half',
                                               name_suffix=ns, agg=av))
            out.append(gen_unpack_dispatcher_corrected_half_nobc(
                I, name_suffix=ns, agg_variant=av, static_=True))
            for bit in range(1, MAX_BIT + 1):
                out.append(gen_unpack_function(bit, I, mode='corrected_quarter',
                                               name_suffix=ns, agg=av))
            out.append(gen_unpack_dispatcher_corrected_quarter_nobc(
                I, name_suffix=ns, agg_variant=av, static_=True))
            # PFOR-exception corrected nobc kernels
            for bit in range(1, MAX_BIT):
                out.append(gen_unpack_function(bit, I, mode='pfor_corrected_uniform',
                                               name_suffix=ns, agg=av))
            out.append(gen_pfor_corrected_dispatcher(I, 'uniform', name_suffix=ns, agg=av))
            for shg in range(4):
                for bit in range(1, MAX_BIT):
                    out.append(gen_unpack_function(bit, I, mode='pfor_corrected_scalar',
                                                   name_suffix=ns, shg=shg, agg=av))
                out.append(gen_pfor_corrected_dispatcher(I, 'scalar', shg=shg,
                                                         name_suffix=ns, agg=av))
            for bit in range(1, MAX_BIT):
                out.append(gen_unpack_function(bit, I, mode='pfor_corrected_half',
                                               name_suffix=ns, agg=av))
            out.append(gen_pfor_corrected_dispatcher(I, 'half', name_suffix=ns, agg=av))
            for bit in range(1, MAX_BIT):
                out.append(gen_unpack_function(bit, I, mode='pfor_corrected_quarter',
                                               name_suffix=ns, agg=av))
            out.append(gen_pfor_corrected_dispatcher(I, 'quarter', name_suffix=ns, agg=av))
        out_path = args.output or os.path.join(
            os.path.dirname(os.path.abspath(__file__)), '..', 'src',
            'simdbitpacking_u16_for_decode_inl.h')
        with open(out_path, 'w') as f:
            f.write("".join(out))
        print(f"Generated {out_path}")
        return

    # Self-contained PFOR in-register exception-merge variant (AVX2, 16-lane).
    # One public symbol simdunpack_u16_pfor; written to its own file so the
    # canonical simdbitpacking_u16.c is never regenerated.
    if args.pfor:
        assert args.width == 256, "pfor variant is AVX2 (256-bit) only"
        reg = I['reg']
        head = (
            "/**\n"
            " * Auto-generated PFOR fused-sum unpack with in-register exception merge.\n"
            " * Generated by gen_simdbitpacking_u16.py --pfor (AVX2, 16 lanes).\n"
            " * Public symbol: simdunpack_u16_pfor. BSD License.\n"
            " */\n"
            "#include <immintrin.h>\n#include <stdint.h>\n#include <stddef.h>\n#include <string.h>\n\n"
            "void simdunpack_u16_pfor(const __m256i *in, uint16_t *out, const uint32_t bit,\n"
            "                         __m256i *sum, const uint16_t *pex, const uint16_t *bm16);\n\n"
            f"static const {reg} kZero = {{0, 0, 0, 0}};\n\n"
            f"static void aggregate_sums_u16({reg} OutReg, {reg}* sum) {{\n"
            f"    *sum = {I['add']}(*sum, {I['unpacklo']}(OutReg, kZero));\n"
            f"    *sum = {I['add']}(*sum, {I['unpackhi']}(OutReg, kZero));\n"
            "}\n\n")
        out = [head, gen_shuffle16_table(), "\n"]
        for bit in range(1, MAX_BIT):  # 1..15
            out.append(gen_unpack_function(bit, I, mode='pfor'))
        out.append(gen_pfor_dispatcher(I))
        out_path = args.output or os.path.join(
            os.path.dirname(os.path.abspath(__file__)), '..', 'src',
            'simdbitpacking_u16_pfor.c')
        with open(out_path, 'w') as f:
            f.write("".join(out))
        print(f"Generated {out_path}")
        return

    # Self-contained FoR-corrected fused-sum unpack + data-store unpack variant.
    # Public symbols simdunpack_u16<suffix>_corrected (per-OutReg corrections array,
    # fused sum) and simdunpack_u16<suffix>_store (classic data-output unpack, used
    # to materialise the FoR anchor / hierarchical local-delta side-streams).
    # Written to its own file so the canonical simdbitpacking_u16.c is untouched.
    if args.corrected:
        reg = I['reg']
        zero_init = "{0, 0}" if args.width == 128 else "{0, 0, 0, 0}"
        head = (
            "/**\n"
            " * Auto-generated FoR-corrected fused-sum unpack + data-store unpack.\n"
            f" * Generated by gen_simdbitpacking_u16.py --corrected "
            f"(width={args.width}, suffix={args.suffix}).\n"
            f" * Public symbols: simdunpack_u16{args.suffix}_corrected,\n"
            f" *                 simdunpack_u16{args.suffix}_store. BSD License.\n"
            " */\n"
            "#include <immintrin.h>\n#include <stdint.h>\n"
            "#include <stddef.h>\n#include <string.h>\n\n"
            f"void simdunpack_u16{args.suffix}_corrected_uniform(const {reg} *in, uint16_t *out,\n"
            f"    const uint32_t bit, const {reg} anchor, {reg} *sum);\n"
            f"void simdunpack_u16{args.suffix}_cscalar0(const {reg} *in, uint16_t *out,\n"
            f"    const uint32_t bit, const uint16_t *a_block, {reg} *sum);\n"
            f"void simdunpack_u16{args.suffix}_cscalar1(const {reg} *in, uint16_t *out,\n"
            f"    const uint32_t bit, const uint16_t *a_block, {reg} *sum);\n"
            f"void simdunpack_u16{args.suffix}_cscalar2(const {reg} *in, uint16_t *out,\n"
            f"    const uint32_t bit, const uint16_t *a_block, {reg} *sum);\n"
            f"void simdunpack_u16{args.suffix}_cscalar3(const {reg} *in, uint16_t *out,\n"
            f"    const uint32_t bit, const uint16_t *a_block, {reg} *sum);\n"
            f"void simdunpack_u16{args.suffix}_corrected_half(const {reg} *in, uint16_t *out,\n"
            f"    const uint32_t bit, const uint16_t *a_block, {reg} *sum);\n"
            + (f"void simdunpack_u16{args.suffix}_corrected_half_shuf(const __m128i *in, uint16_t *out,\n"
               f"    const uint32_t bit, const uint16_t *a_block, __m128i *sum);\n"
               f"void simdunpack_u16{args.suffix}_cscalar_shuf0(const __m128i *in, uint16_t *out,\n"
               f"    const uint32_t bit, const uint16_t *a_block, __m128i *sum);\n"
               f"void simdunpack_u16{args.suffix}_cscalar_shuf1(const __m128i *in, uint16_t *out,\n"
               f"    const uint32_t bit, const uint16_t *a_block, __m128i *sum);\n"
               f"void simdunpack_u16{args.suffix}_cscalar_shuf2(const __m128i *in, uint16_t *out,\n"
               f"    const uint32_t bit, const uint16_t *a_block, __m128i *sum);\n"
               f"void simdunpack_u16{args.suffix}_cscalar_shuf3(const __m128i *in, uint16_t *out,\n"
               f"    const uint32_t bit, const uint16_t *a_block, __m128i *sum);\n"
               if args.width == 128 else "")
            + (f"void simdunpack_u16{args.suffix}_cscalar_shuf0(const {reg} *in, uint16_t *out,\n"
               f"    const uint32_t bit, const uint16_t *a_block, {reg} *sum);\n"
               f"void simdunpack_u16{args.suffix}_cscalar_shuf1(const {reg} *in, uint16_t *out,\n"
               f"    const uint32_t bit, const uint16_t *a_block, {reg} *sum);\n"
               f"void simdunpack_u16{args.suffix}_cscalar_shuf2(const {reg} *in, uint16_t *out,\n"
               f"    const uint32_t bit, const uint16_t *a_block, {reg} *sum);\n"
               f"void simdunpack_u16{args.suffix}_cscalar_shuf3(const {reg} *in, uint16_t *out,\n"
               f"    const uint32_t bit, const uint16_t *a_block, {reg} *sum);\n"
               f"void simdunpack_u16{args.suffix}_corrected_half_shuf(const {reg} *in, uint16_t *out,\n"
               f"    const uint32_t bit, const uint16_t *a_block, {reg} *sum);\n"
               f"void simdunpack_u16{args.suffix}_corrected_quarter(const {reg} *in, uint16_t *out,\n"
               f"    const uint32_t bit, const uint16_t *a_block, {reg} *sum);\n"
               f"void simdunpack_u16{args.suffix}_corrected_quarter_shuf(const {reg} *in, uint16_t *out,\n"
               f"    const uint32_t bit, const uint16_t *a_block, {reg} *sum);\n"
               if args.width == 256 else "")
            + f"void simdunpack_u16{args.suffix}_store(const {reg} *in, uint16_t *out,\n"
            f"    const uint32_t bit);\n\n"
            f"static const {reg} kZero = {zero_init};\n\n"
            f"static void aggregate_sums_u16({reg} OutReg, {reg}* sum) {{\n"
            f"    *sum = {I['add']}(*sum, {I['unpacklo']}(OutReg, kZero));\n"
            f"    *sum = {I['add']}(*sum, {I['unpackhi']}(OutReg, kZero));\n"
            "}\n\n"
            "/* madd-widen aggregate: one port-0/1 op instead of two port-5\n"
            "   shuffles. Signed, so the codec uses it only when all decoded\n"
            "   values < 2^15 (the `_madd` dispatcher variants). */\n"
            f"__attribute__((unused))\n"
            f"static void aggregate_sums_u16_madd({reg} OutReg, {reg}* sum) {{\n"
            f"    *sum = {I['add']}(*sum, {I['madd16']}(OutReg, {I['set1']}(1)));\n"
            "}\n\n"
            "/* benchmark-only: produce OutReg but skip the widening sum (cheap XOR\n"
            "   sink keeps OutReg live). Sums are wrong — for timing the\n"
            "   OutReg-production cost only (codec path behind FOR_DECODE_NOAGG). */\n"
            f"__attribute__((unused))\n"
            f"static void aggregate_sums_u16_noagg({reg} OutReg, {reg}* sum) {{\n"
            f"    *sum = {I['xor_fn']}(*sum, OutReg);\n"
            "}\n\n")
        out = [head, gen_null_unpacker(I)]
        # unpack (always-correct), madd (values<2^15), noagg (bench-only).
        for agg in ('unpack', 'madd', 'noagg'):
            for bit in range(1, MAX_BIT + 1):
                out.append(gen_unpack_function(bit, I, mode='corrected_uniform',
                                               name_suffix=args.suffix, agg=agg))
            out.append(gen_unpack_dispatcher_corrected_uniform(
                I, name_suffix=args.suffix, agg=agg))
            for shg in range(4):  # shg = log2(w/lanes): 128→w=8,16,32,64; 256→w=16,32,64,128
                for bit in range(1, MAX_BIT + 1):
                    out.append(gen_unpack_function(bit, I, mode='corrected_scalar',
                                                   name_suffix=args.suffix, shg=shg,
                                                   agg=agg))
                out.append(gen_unpack_dispatcher_corrected_scalar(
                    I, shg, name_suffix=args.suffix, agg=agg))
            # scalar_shuf: vmovq+(vbroadcasti128+)vpshufb variant of corrected_scalar.
            for shg in range(4):
                for bit in range(1, MAX_BIT + 1):
                    out.append(gen_unpack_function(bit, I, mode='corrected_scalar_shuf',
                                                   name_suffix=args.suffix, shg=shg,
                                                   agg=agg))
                out.append(gen_unpack_dispatcher_corrected_scalar_shuf(
                    I, shg, name_suffix=args.suffix, agg=agg))
            # half: w==lanes/2 (128→w=4, 256→w=8) — OutReg straddles two windows.
            for bit in range(1, MAX_BIT + 1):
                out.append(gen_unpack_function(bit, I, mode='corrected_half',
                                               name_suffix=args.suffix, agg=agg))
            out.append(gen_unpack_dispatcher_corrected_half(
                I, name_suffix=args.suffix, agg=agg))
            # half_shuf: shuffle-based variant of corrected_half (both widths).
            for bit in range(1, MAX_BIT + 1):
                out.append(gen_unpack_function(bit, I, mode='corrected_half_shuf',
                                               name_suffix=args.suffix, agg=agg))
            out.append(gen_unpack_dispatcher_corrected_half_shuf(
                I, name_suffix=args.suffix, agg=agg))
            # quarter + quarter_shuf: w==4 (256 only) — OutReg straddles four 4-lane windows.
            if args.width == 256:
                for bit in range(1, MAX_BIT + 1):
                    out.append(gen_unpack_function(bit, I, mode='corrected_quarter',
                                                   name_suffix=args.suffix, agg=agg))
                out.append(gen_unpack_dispatcher_corrected_quarter(
                    I, name_suffix=args.suffix, agg=agg))
                for bit in range(1, MAX_BIT + 1):
                    out.append(gen_unpack_function(bit, I, mode='corrected_quarter_shuf',
                                                   name_suffix=args.suffix, agg=agg))
                out.append(gen_unpack_dispatcher_corrected_quarter_shuf(
                    I, name_suffix=args.suffix, agg=agg))
        for bit in range(1, MAX_BIT + 1):  # store: data-output, no aggregate
            out.append(gen_unpack_function(bit, I, mode='store',
                                           name_suffix=args.suffix))
        out.append(gen_unpack_dispatcher_store(I, name_suffix=args.suffix))
        out_path = args.output or os.path.join(
            os.path.dirname(os.path.abspath(__file__)), '..', 'src',
            f'simdbitpacking_u16{args.suffix}_corrected.c')
        with open(out_path, 'w') as f:
            f.write("".join(out))
        print(f"Generated {out_path}")
        return

    # nobc (plain aggregate + scalar anchor) variants — self-contained per-width file.
    # Emits corrected_uniform/cscalar0-3/half/quarter in nobc and nobc_madd agg variants.
    # aggregate_sums_u16_nobc*(OutReg, const uint16_t* a, uint64_t* scalar_acc, sum):
    #   plain widen-sum + *scalar_acc += lpa * relevant_anchor(s).
    if args.anc:
        assert args.suffix, "--anc requires --suffix"
        ns = args.suffix
        reg = I['reg']
        lanes = I['lanes']
        half_lanes = lanes // 2
        quarter_lanes = lanes // 4 if args.width == 256 else None
        out = []
        out.append(
            f"/**\n"
            f" * Auto-generated FoR nobc fused-sum unpack (plain aggregate + scalar anchor).\n"
            f" * Generated by gen_simdbitpacking_u16.py --anc "
            f"(width={args.width}, suffix={ns})\n"
            f" *\n"
            f" * Per OutReg: plain widen-sum into *sum, plus:\n"
            f" *   aggregate_sums_u16_nobc(OutReg, a, scalar_acc, sum)  — 1 anchor/OutReg\n"
            f" *   aggregate_sums_u16_nobc_half(...)                   — 2 anchors/OutReg\n"
            f" *   aggregate_sums_u16_nobc_quarter(...)                 — 4 anchors/OutReg (256)\n"
            f" * No SIMD anchor correction is added to the OutReg.\n"
            f" */\n"
            f"#include <immintrin.h>\n"
            f"#include <stdint.h>\n"
            f"#include <stddef.h>\n\n"
        )
        zero_init = "{0, 0}" if args.width == 128 else "{0, 0, 0, 0}"
        out.append(f"static const {reg} kZero = {zero_init};\n\n")
        # nobc_sum_t: native GCC vector type WITHOUT __may_alias__.
        # GCC's __m256i/__m128i carry __may_alias__, meaning writes through
        # __m256i* force reloads of any other pointer (including anchor a[]).
        # Using a custom typedef without may_alias for the sum accumulator pointer
        # lets GCC hoist a[0] across all per-OutReg vpaddd/vpmaddwd stores.
        # __m256i storage is safe to access through nobc_sum_t* (the may_alias on
        # __m256i permits access from any type; the non-aliasingness goes one way).
        nbytes = args.width // 8
        out.append(f"typedef int nobc_sum_t __attribute__((vector_size({nbytes})));\n\n")
        out.append(
            f"static void aggregate_sums_u16_nobc({reg} OutReg,"
            f" const uint16_t * __restrict__ a,"
            f" uint64_t * __restrict__ scalar_acc, nobc_sum_t * __restrict__ sum) {{\n"
            f"    {reg} _sv = ({reg})(*sum);\n"
            f"    _sv = {I['add']}(_sv, {I['unpacklo']}(OutReg, kZero));\n"
            f"    _sv = {I['add']}(_sv, {I['unpackhi']}(OutReg, kZero));\n"
            f"    *sum = (nobc_sum_t)_sv;\n"
            f"    *scalar_acc += {lanes}ULL * (uint64_t)a[0];\n"
            f"}}\n\n"
            f"static void aggregate_sums_u16_nobc_madd({reg} OutReg,"
            f" const uint16_t * __restrict__ a,"
            f" uint64_t * __restrict__ scalar_acc, nobc_sum_t * __restrict__ sum) {{\n"
            f"    {reg} _sv = ({reg})(*sum);\n"
            f"    _sv = {I['add']}(_sv, {I['madd16']}(OutReg, {I['set1']}(1)));\n"
            f"    *sum = (nobc_sum_t)_sv;\n"
            f"    *scalar_acc += {lanes}ULL * (uint64_t)a[0];\n"
            f"}}\n\n"
            # half: 2 anchors per OutReg, lanes/2 elements each
            f"static void aggregate_sums_u16_nobc_half({reg} OutReg,"
            f" const uint16_t * __restrict__ a,"
            f" uint64_t * __restrict__ scalar_acc, nobc_sum_t * __restrict__ sum) {{\n"
            f"    {reg} _sv = ({reg})(*sum);\n"
            f"    _sv = {I['add']}(_sv, {I['unpacklo']}(OutReg, kZero));\n"
            f"    _sv = {I['add']}(_sv, {I['unpackhi']}(OutReg, kZero));\n"
            f"    *sum = (nobc_sum_t)_sv;\n"
            f"    *scalar_acc += {half_lanes}ULL * (uint64_t)a[0]"
            f" + {half_lanes}ULL * (uint64_t)a[1];\n"
            f"}}\n\n"
            f"static void aggregate_sums_u16_nobc_half_madd({reg} OutReg,"
            f" const uint16_t * __restrict__ a,"
            f" uint64_t * __restrict__ scalar_acc, nobc_sum_t * __restrict__ sum) {{\n"
            f"    {reg} _sv = ({reg})(*sum);\n"
            f"    _sv = {I['add']}(_sv, {I['madd16']}(OutReg, {I['set1']}(1)));\n"
            f"    *sum = (nobc_sum_t)_sv;\n"
            f"    *scalar_acc += {half_lanes}ULL * (uint64_t)a[0]"
            f" + {half_lanes}ULL * (uint64_t)a[1];\n"
            f"}}\n\n"
        )
        if args.width == 256:
            out.append(
                # quarter: 4 anchors per OutReg, lanes/4 elements each
                f"static void aggregate_sums_u16_nobc_quarter({reg} OutReg,"
                f" const uint16_t * __restrict__ a,"
                f" uint64_t * __restrict__ scalar_acc, nobc_sum_t * __restrict__ sum) {{\n"
                f"    {reg} _sv = ({reg})(*sum);\n"
                f"    _sv = {I['add']}(_sv, {I['unpacklo']}(OutReg, kZero));\n"
                f"    _sv = {I['add']}(_sv, {I['unpackhi']}(OutReg, kZero));\n"
                f"    *sum = (nobc_sum_t)_sv;\n"
                f"    *scalar_acc += {quarter_lanes}ULL * ((uint64_t)a[0]"
                f" + (uint64_t)a[1] + (uint64_t)a[2] + (uint64_t)a[3]);\n"
                f"}}\n\n"
                f"static void aggregate_sums_u16_nobc_quarter_madd({reg} OutReg,"
                f" const uint16_t * __restrict__ a,"
                f" uint64_t * __restrict__ scalar_acc, nobc_sum_t * __restrict__ sum) {{\n"
                f"    {reg} _sv = ({reg})(*sum);\n"
                f"    _sv = {I['add']}(_sv, {I['madd16']}(OutReg, {I['set1']}(1)));\n"
                f"    *sum = (nobc_sum_t)_sv;\n"
                f"    *scalar_acc += {quarter_lanes}ULL * ((uint64_t)a[0]"
                f" + (uint64_t)a[1] + (uint64_t)a[2] + (uint64_t)a[3]);\n"
                f"}}\n\n"
            )
        # per-bit inner functions + dispatchers for nobc and nobc_madd
        for av in ('nobc', 'nobc_madd'):
            for bit in range(1, MAX_BIT + 1):
                out.append(gen_unpack_function(
                    bit, I, mode='corrected_uniform', name_suffix=ns, agg=av))
            out.append(gen_unpack_dispatcher_corrected_uniform_nobc(
                I, name_suffix=ns, agg_variant=av, static_=False))
            for shg in range(4):
                for bit in range(1, MAX_BIT + 1):
                    out.append(gen_unpack_function(
                        bit, I, mode='corrected_scalar', name_suffix=ns, shg=shg, agg=av))
                out.append(gen_unpack_dispatcher_corrected_scalar_nobc(
                    I, shg, name_suffix=ns, agg_variant=av, static_=False))
            for bit in range(1, MAX_BIT + 1):
                out.append(gen_unpack_function(
                    bit, I, mode='corrected_half', name_suffix=ns, agg=av))
            out.append(gen_unpack_dispatcher_corrected_half_nobc(
                I, name_suffix=ns, agg_variant=av, static_=False))
            if args.width == 256:
                for bit in range(1, MAX_BIT + 1):
                    out.append(gen_unpack_function(
                        bit, I, mode='corrected_quarter', name_suffix=ns, agg=av))
                out.append(gen_unpack_dispatcher_corrected_quarter_nobc(
                    I, name_suffix=ns, agg_variant=av, static_=False))
        out_path = os.path.join(
            os.path.dirname(os.path.abspath(__file__)), '..', 'src',
            f'simdbitpacking_u16{ns}_nobc.c')
        with open(out_path, 'w') as f:
            f.write("".join(out))
        print(f"Generated {out_path}")
        return

    # Minimal self-contained variant: only the plain pack/unpack path, with
    # suffixed public symbols so it can coexist with the canonical build.
    if args.suffix:
        out = [gen_header(I, suffix=args.suffix), gen_null_unpacker(I)]
        for bit in range(MAX_BIT + 1):
            out.append(gen_pack_function(bit, I))
        out.append(gen_pack_dispatcher(I, suffix=args.suffix))
        for agg in ('unpack', 'madd', 'noagg'):
            for bit in range(1, MAX_BIT + 1):
                out.append(gen_unpack_function(bit, I, mode='plain', agg=agg))
            out.append(gen_unpack_dispatcher(I, suffix=args.suffix, agg=agg))
        out_path = args.output or os.path.join(
            os.path.dirname(os.path.abspath(__file__)), '..', 'src',
            f'simdbitpacking_u16{args.suffix}.c')
        with open(out_path, 'w') as f:
            f.write("".join(out))
        print(f"Generated {out_path}")
        return

    out = []
    out.append(gen_header(I))
    out.append(gen_null_unpacker(I))

    # Pack functions for all bit widths
    for bit in range(MAX_BIT + 1):
        out.append(gen_pack_function(bit, I))

    out.append(gen_pack_dispatcher(I))

    # Unpack+sum functions for all bit widths
    for bit in range(1, MAX_BIT + 1):
        out.append(gen_unpack_function(bit, I, mode='plain'))

    out.append(gen_unpack_dispatcher(I))

    # AVX2-only: delta-local and delta-carry unpack functions + dispatchers.
    if I['width'] == 256:
        for bit in range(1, MAX_BIT + 1):
            out.append(gen_unpack_function(bit, I, mode='delta_local'))
        out.append(gen_unpack_dispatcher_delta_local(I))

        for bit in range(1, MAX_BIT + 1):
            out.append(gen_unpack_function(bit, I, mode='delta_carry'))
        out.append(gen_unpack_dispatcher_delta_carry(I))

        for bit in range(1, MAX_BIT + 1):
            out.append(gen_unpack_function(bit, I, mode='corrected'))
        out.append(gen_unpack_dispatcher_corrected(I))

        for bit in range(1, MAX_BIT + 1):
            out.append(gen_unpack_function(bit, I, mode='corrected_uniform'))
        out.append(gen_unpack_dispatcher_corrected_uniform(I))

    # Sub-block variants for W=128 (8 OutRegs): pack + corrected_uniform unpack.
    # Only generated for AVX2 (256-bit) since the FoR-global codecs are AVX2-only.
    if I['width'] == 256:
        for W in [32, 64, 128]:
          name_suffix = f'_n{W}'
          I_sub = dict(I, block=W)
          for bit in range(MAX_BIT + 1):
              out.append(gen_pack_function(bit, I_sub, name_suffix=name_suffix))
          for bit in range(1, MAX_BIT + 1):
              out.append(gen_unpack_function(bit, I_sub, mode='corrected_uniform',
                                             name_suffix=name_suffix))
          out.append(gen_pack_dispatcher_nW(I_sub, W, name_suffix))
          out.append(gen_unpack_dispatcher_corrected_uniform_nW(I_sub, W, name_suffix))

    # Short-length handlers
    out.append(gen_shortlength_pack(I))
    out.append(gen_shortlength_unpack(I))

    # Utility functions
    out.append(gen_utility_functions(I))

    script_dir = os.path.dirname(os.path.abspath(__file__))
    src_dir = os.path.join(script_dir, '..', 'src')
    out_path = os.path.join(src_dir, 'simdbitpacking_u16.c')

    with open(out_path, 'w') as f:
        f.write("".join(out))
    print(f"Generated {out_path}")


if __name__ == "__main__":
    main()
